// Turn the proved case tables into the module the app reads.
//
//   node regen-case-tables.mjs           # rewrites lib/data/case-tables.js
//   node regen-case-tables.mjs --check   # prints what it would write to stdout, changes nothing
//
// `crates/optimal-solver/tables/*.json` is the artifact: generated by the Rust searches, covered
// by the certificates beside it, and checked on every `cargo test` run by
// `crates/optimal-solver/tests/committed_tables.rs`. This script does not decide anything — it
// copies, drops the zero-length rows, and writes a form the browser can import synchronously.
//
// **Why a JS module and not the JSON.** The solver is synchronous: `stage.run(state, steps)` has
// nowhere to await a fetch, and the one JSON the app does load at runtime already fails outside a
// browser ("the library is at a file: URL, which fetch cannot read"), which would make every
// generated rung untestable in node. An ES module is synchronous everywhere, needs no build step
// in a repository that serves raw modules, and cannot half-load.
//
// The output is COMMITTED and `case-tables.test.mjs` re-runs this script and diffs it, so a
// hand-edit or a stale copy fails rather than shipping.

import { readFileSync, realpathSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const SOURCES = [
  {
    binding: 'FULL_OLL',
    file: 'oll.json',
    count: 57,
    doc: `/**
 * Full OLL: one algorithm per case, so the top face is one look rather than two.
 *
 * Proved minimal in half-turn metric by \`crates/optimal-solver\`, and certified — every length
 * carries the exhausted contour below it, over all 1,152 (alignment, goal) pairs. Mean 9.37,
 * longest 12.
 */`,
  },
  {
    binding: 'FULL_PLL',
    file: 'pll.json',
    count: 21,
    doc: `/**
 * Full PLL: one algorithm per case. Mean 11.4762 over the 21 cases, longest 14.
 *
 * Not to be confused with 11.642361, which is the mean over the 288 last-layer PERMUTATIONS and is
 * the number that matches Cube Explorer's published histogram bucket for bucket — the one place
 * this repository has an external figure to agree with. A case is an orbit of states under the two
 * alignments, so the two means are averages over different things and differ by 0.166.
 */`,
  },
  {
    binding: 'F2L_CASES',
    file: 'f2l.json',
    count: 41,
    doc: `/**
 * The 41 F2L cases, read in the frame where the working slot is at the front right.
 *
 * Mean 6.90, longest 9. Not every position a solve meets is one of these: a piece buried in
 * ANOTHER pair's slot cannot be reached by a maneuver that leaves that slot alone, so those fall
 * back to the rung below. That is structural, not a gap in the table —
 * \`f2l-configurations.test.mjs\` enumerates the whole space and splits it 150 to 234.
 */`,
  },
];

const HEADER = `// GENERATED FILE — do not edit by hand.
//
//   node regen-case-tables.mjs
//
// The algorithms the one-look rungs are made of, copied from the proved tables in
// \`crates/optimal-solver/tables/\`. Those are the artifact: searched, certified, and re-checked
// against their certificates on every \`cargo test\` run. This file is a transport, and
// \`case-tables.test.mjs\` re-runs the generator and diffs it, so it cannot drift from them.
//
// **The names are IDENTIFIERS, not case names.** \`oll:1a2b3c4d\` is this repository's key for a
// case, derived from the position; it is not the number a learner would find on any other site,
// and inventing our own numbering would be worse than showing none. \`method-lesson.js\` carries
// them on the step and declines to print them, for exactly that reason.
`;

const root = new URL('../../crates/optimal-solver/tables/', import.meta.url);

function render() {
  const blocks = SOURCES.map(({ binding, file, count, doc }) => {
    const table = JSON.parse(readFileSync(new URL(file, root), 'utf8'));
    // The zero-length row is the case that is already done. It belongs in the artifact — a table
    // missing a case is a lookup that misses — and not in a repertoire, where an empty algorithm
    // is the shortest candidate there is and would be preferred over every real one.
    const rows = table.cases.filter((c) => c.length > 0);
    if (rows.length !== count) {
      throw new Error(`${file}: ${rows.length} cases with an algorithm, expected ${count}`);
    }
    for (const row of rows) {
      if (!/^[URFDLB][2']? (?:[URFDLB][2']? )*[URFDLB][2']?$/.test(row.alg)) {
        throw new Error(`${file}: ${row.case} is not a face-turn maneuver: "${row.alg}"`);
      }
      if (row.alg.split(' ').length !== row.length) {
        throw new Error(`${file}: ${row.case} claims ${row.length} moves and has ${row.alg}`);
      }
    }
    const entries = rows
      .map((c) => `  Object.freeze({ name: '${c.case}', alg: "${c.alg}" }),`)
      .join('\n');
    return `${doc}\nexport const ${binding} = Object.freeze([\n${entries}\n]);\n`;
  });
  return `${HEADER}\n${blocks.join('\n')}`;
}

const out = new URL('./lib/data/case-tables.js', import.meta.url);

/**
 * Was this file run, or imported?
 *
 * **The guard that was missing, and what it cost.** `case-tables.test.mjs` imports `render` to
 * diff the committed module against a fresh one — and importing ran everything below, which
 * REWROTE that module before the diff read it. The one test whose whole purpose is to catch a
 * hand-edited or stale `case-tables.js` restored the file and then found it identical. Verified:
 * corrupting an algorithm and running the suite left that test green and the corruption gone.
 *
 * `pathToFileURL` rather than string interpolation, and the entry path canonicalized first:
 * `import.meta.url` is the realpath of this file while `process.argv[1]` is whatever the caller
 * typed, and a path containing `#`, `?` or `%` means something to a URL parser. Either difference
 * turns this into a module that quietly does nothing.
 */
function isDirectEntry() {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    if (import.meta.url === pathToFileURL(realpathSync(entry)).href) return true;
  } catch {
    // Not resolvable — fall through rather than assuming "imported".
  }
  return import.meta.url === pathToFileURL(entry).href;
}

function main(argv) {
  const body = render();
  // `Buffer.byteLength`, not `String.length`: the latter counts UTF-16 code units, so the header's
  // non-ASCII characters made every reported figure smaller than the file. The committed module is
  // 10,814 UTF-8 bytes and used to be announced as 10,806.
  const bytes = Buffer.byteLength(body, 'utf8');
  if (argv.includes('--check')) {
    // The generated content on stdout, as the usage line says — so `--check > /tmp/x` gives
    // something to look at — and the verdict on stderr, so a pipeline reads one and a person the
    // other.
    process.stdout.write(body);
    const same = readFileSync(out, 'utf8') === body;
    console.error(`${bytes} bytes — the committed file is ${same ? 'identical' : 'DIFFERENT'}`);
    process.exit(same ? 0 : 1);
  }
  writeFileSync(out, body);
  console.error(`wrote ${out.pathname} — ${bytes} bytes`);
}

if (isDirectEntry()) main(process.argv.slice(2));

export { main, render };
